double cross(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.y - a.y) - (b.y - a.y) * (c.x - a.x);
}

double dot(Point a, Point b, Point c) {
    return (b.x - a.x) * (c.x - a.x) + (b.y - a.y) * (c.y - a.y);
}

double dist2(Point a, Point b) {
    double dx = a.x - b.x, dy = a.y - b.y;
    return dx*dx + dy*dy;
}

double dist(Point a, Point b) {
    return sqrt(dist2(a, b));
}

int pointInConvexPoly(Point p) {
    int sign = 0;
    for (int i = 0; i < n; i++) {
        double c = cross(poly[i], poly[(i+1)%n], p);
        if (fabs(c) < EPS) continue;
        int s = (c > 0) ? 1 : -1;
        if (sign == 0) sign = s;
        else if (sign != s) return 0;
    }
    return 1;
}

// area of intersection between circle center c radius R and polygon
double circlePolyIntersection(Point c) {
    double area = 0.0;
    for (int i = 0; i < n; i++) {
        Point A = poly[i], B = poly[(i+1)%n];
        double a = dist(B, A);
        double b = dist(c, A);
        double cdist = dist(c, B);

        double angleA = atan2(A.y - c.y, A.x - c.x);
        double angleB = atan2(B.y - c.y, B.x - c.x);
        double dangle = angleB - angleA;
        if (dangle > M_PI) dangle -= 2*M_PI;
        else if (dangle < -M_PI) dangle += 2*M_PI;

        int insideA = (b <= R + EPS);
        int insideB = (cdist <= R + EPS);

        if (insideA && insideB) {
            area += cross(c, A, B) / 2.0;
        } else if (!insideA && !insideB) {
            double proj = dot(A, B, c) / (a*a);
            Point closest = {A.x + proj*(B.x - A.x), A.y + proj*(B.y - A.y)};
            double d = dist(c, closest);
            if (d < R - EPS && proj > 0 && proj < 1) {
                double theta = acos(d / R);
                double base = sqrt(R*R - d*d);
                area += R*R*theta - d*base;
                double ang1 = atan2(A.y - closest.y, A.x - closest.x);
                double ang2 = atan2(B.y - closest.y, B.x - closest.x);
                double dang = ang2 - ang1;
                if (dang > M_PI) dang -= 2*M_PI;
                else if (dang < -M_PI) dang += 2*M_PI;
                area += 0.5 * R * R * fabs(sin(dang));
            } else {
                area += 0.5 * R * R * dangle;
            }
        } else {
            Point P = insideA ? B : A;
            Point Q = insideA ? A : B;
            double t = dot(Q, P, c) / (a*a);
            if (t < 0) t = 0;
            if (t > 1) t = 1;
            Point closest = {Q.x + t*(P.x - Q.x), Q.y + t*(P.y - Q.y)};
            double d = dist(c, closest);
            double theta = acos(d / R);
            double base = sqrt(R*R - d*d);
            area += 0.5 * R * R * dangle;
            double ang = atan2(P.y - closest.y, P.x - closest.x) - atan2(Q.y - closest.y, Q.x - closest.x);
            if (ang > M_PI) ang -= 2*M_PI;
            else if (ang < -M_PI) ang += 2*M_PI;
            area += 0.5 * R * R * fabs(sin(ang));
        }
    }
    return fabs(area);
}

double solve() {
    double best = 0.0;
    // Try vertices
    for (int i = 0; i < n; i++) {
        double a = circlePolyIntersection(poly[i]);
        if (a > best) best = a;
    }
    // Try points along perpendicular to edges
    for (int i = 0; i < n; i++) {
        Point A = poly[i], B = poly[(i+1)%n];
        double dx = B.x - A.x, dy = B.y - A.y;
        double len = sqrt(dx*dx + dy*dy);
        double nx = -dy/len, ny = dx/len;
        for (int sign = -1; sign <= 1; sign += 2) {
            double lo = -R, hi = R;
            for (int iter = 0; iter < 60; iter++) {
                double m1 = lo + (hi-lo)/3;
                double m2 = hi - (hi-lo)/3;
                Point p1 = {A.x + nx*m1, A.y + ny*m1};
                Point p2 = {A.x + nx*m2, A.y + ny*m2};
                double v1 = circlePolyIntersection(p1);
                double v2 = circlePolyIntersection(p2);
                if (v1 < v2) lo = m1;
                else hi = m2;
            }
            Point bestp = {A.x + nx*lo, A.y + ny*lo};
            double val = circlePolyIntersection(bestp);
            if (val > best) best = val;
        }
    }
    return best;
}

