#include <stdio.h>
#include <stdlib.h>
#include <math.h>

#define EPS 1e-10

typedef struct {
    double x, y;
} Point;

typedef struct {
    Point a, b;
} Segment;

static Point make_point(double x, double y) {
    Point p; p.x = x; p.y = y; return p;
}

static Point add(Point a, Point b) { return make_point(a.x + b.x, a.y + b.y); }
static Point sub(Point a, Point b) { return make_point(a.x - b.x, a.y - b.y); }
static Point mul(Point a, double k) { return make_point(a.x * k, a.y * k); }

static double dot(Point a, Point b) { return a.x * b.x + a.y * b.y; }
static double cross(Point a, Point b) { return a.x * b.y - a.y * b.x; }
static double norm2(Point a) { return dot(a, a); }
static double dist2(Point a, Point b) { return norm2(sub(a, b)); }

static int cmp_double(const void *pa, const void *pb) {
    double a = *(const double*)pa;
    double b = *(const double*)pb;
    if (a < b) return -1;
    if (a > b) return 1;
    return 0;
}

/* Clip convex polygon by half-plane cross(dir, p - a) >= 0 */
static int clip_polygon(Point *poly, int n, Point a, Point b, Point *out) {
    Point dir = sub(b, a);
    int m = 0;
    for (int i = 0; i < n; i++) {
        Point p = poly[i];
        Point q = poly[(i + 1) % n];
        double cp = cross(dir, sub(p, a));
        double cq = cross(dir, sub(q, a));
        int inp = cp >= -EPS;
        int inq = cq >= -EPS;

        if (inp && inq) {
            out[m++] = q;
        } else if (inp && !inq) {
            Point pq = sub(q, p);
            double denom = cross(dir, pq);
            if (fabs(denom) > EPS) {
                double t = -cross(dir, sub(p, a)) / denom;
                out[m++] = add(p, mul(pq, t));
            }
        } else if (!inp && inq) {
            Point pq = sub(q, p);
            double denom = cross(dir, pq);
            if (fabs(denom) > EPS) {
                double t = -cross(dir, sub(p, a)) / denom;
                out[m++] = add(p, mul(pq, t));
            }
            out[m++] = q;
        }
    }
    return m;
}

/* point in convex polygon boundary included, polygon CCW */
static int point_in_convex(Point *poly, int n, Point p) {
    for (int i = 0; i < n; i++) {
        Point a = poly[i], b = poly[(i + 1) % n];
        if (cross(sub(b, a), sub(p, a)) < -EPS) return 0;
    }
    return 1;
}

/* distance^2 from point p to segment ab */
static double point_seg_dist2(Point p, Point a, Point b) {
    Point ab = sub(b, a);
    double len2 = norm2(ab);
    if (len2 < EPS) return dist2(p, a);
    double t = dot(sub(p, a), ab) / len2;
    if (t < 0) t = 0;
    if (t > 1) t = 1;
    Point proj = add(a, mul(ab, t));
    return dist2(p, proj);
}

/* Check if disk centered at c radius r covers polygon */
static int covers_polygon(Point *poly, int n, Point c, double r) {
    double r2 = r * r + 1e-9;
    for (int i = 0; i < n; i++) {
        if (dist2(poly[i], c) > r2) return 0;
    }
    return 1;
}

/* Build Voronoi cell of vertex id within polygon */
static int build_cell(Point *poly, int n, int id, Point *cell) {
    Point tmp1[512], tmp2[512];
    int m = n;
    for (int i = 0; i < n; i++) tmp1[i] = poly[i];

    Point vi = poly[id];
    for (int j = 0; j < n; j++) if (j != id) {
        Point vj = poly[j];
        Point mid = mul(add(vi, vj), 0.5);
        Point d = sub(vj, vi);

        /* Keep points x such that |x-vi|^2 <= |x-vj|^2
           equivalent to dot(x-mid, d) <= 0
           i.e. cross(d_rot, x-mid) >= 0 with d_rot=(d.y,-d.x) */
        Point a = mid;
        Point b = add(mid, make_point(d.y, -d.x));
        m = clip_polygon(tmp1, m, a, b, tmp2);
        if (m == 0) return 0;
        for (int k = 0; k < m; k++) tmp1[k] = tmp2[k];
    }
    for (int i = 0; i < m; i++) cell[i] = tmp1[i];
    return m;
}

/* Intersections of segment ab with circle centered c radius r */
static int seg_circle_intersections(Point a, Point b, Point c, double r, Point *out) {
    Point d = sub(b, a);
    Point f = sub(a, c);
    double A = dot(d, d);
    double B = 2.0 * dot(f, d);
    double C = dot(f, f) - r * r;
    double D = B * B - 4 * A * C;
    if (D < -EPS) return 0;
    int cnt = 0;
    if (D < 0) D = 0;
    double sq = sqrt(D);
    double t1 = (-B - sq) / (2 * A);
    double t2 = (-B + sq) / (2 * A);
    if (t1 > -EPS && t1 < 1 + EPS) out[cnt++] = add(a, mul(d, t1));
    if (D > EPS && t2 > -EPS && t2 < 1 + EPS) out[cnt++] = add(a, mul(d, t2));
    return cnt;
}

/* Circle-circle intersections */
static int circle_circle_intersections(Point c1, double r1, Point c2, double r2, Point *out) {
    Point dvec = sub(c2, c1);
    double d = sqrt(norm2(dvec));
    if (d < EPS) return 0;
    if (d > r1 + r2 + EPS) return 0;
    if (d < fabs(r1 - r2) - EPS) return 0;

    double a = (r1*r1 - r2*r2 + d*d) / (2*d);
    double h2 = r1*r1 - a*a;
    if (h2 < -EPS) return 0;
    if (h2 < 0) h2 = 0;
    double h = sqrt(h2);

    Point p = add(c1, mul(dvec, a / d));
    Point perp = make_point(-dvec.y / d, dvec.x / d);

    out[0] = add(p, mul(perp, h));
    if (h < EPS) return 1;
    out[1] = add(p, mul(perp, -h));
    return 2;
}

/* Candidate centers where nearest polygon point is a given vertex */
static void add_candidate(Point *cand, int *cnt, Point p) {
    for (int i = 0; i < *cnt; i++) {
        if (dist2(cand[i], p) < 1e-16) return;
    }
    cand[(*cnt)++] = p;
}

static double solve(Point *poly, int n, double r) {
    if (n == 1) return 0.0;
    if (n == 2) {
        double d = sqrt(dist2(poly[0], poly[1]));
        return (d <= 2*r + EPS) ? d : 2*r;
    }

    /* If some center can cover entire polygon, answer is polygon area */
    Point cell[512];
    for (int i = 0; i < n; i++) {
        int m = build_cell(poly, n, i, cell);
        if (m == 0) continue;
        for (int j = 0; j < m; j++) {
            if (dist2(cell[j], poly[i]) <= r*r + 1e-9) {
                if (covers_polygon(poly, n, cell[j], r)) {
                    return 2.0 * r; /* width formula later? no */
                }
            }
        }
    }

    /* We maximize 2*sqrt(r^2 - d^2), where d is min distance from center to polygon.
       Since center inside polygon, nearest point lies on boundary.
       For each Voronoi region of a vertex, minimize distance to that vertex. */
    double bestd2 = 1e100;

    for (int i = 0; i < n; i++) {
        int m = build_cell(poly, n, i, cell);
        if (m == 0) continue;

        Point cand[2048];
        int cnt = 0;

        /* cell vertices */
        for (int j = 0; j < m; j++) add_candidate(cand, &cnt, cell[j]);

        /* projection of vertex onto each cell edge */
        for (int j = 0; j < m; j++) {
            Point a = cell[j], b = cell[(j + 1) % m];
            Point ab = sub(b, a);
            double len2 = norm2(ab);
            if (len2 < EPS) continue;
            double t = dot(sub(poly[i], a), ab) / len2;
            if (t > -EPS && t < 1 + EPS) {
                Point p = add(a, mul(ab, t));
                add_candidate(cand, &cnt, p);
            }
            Point inters[2];
            int k = seg_circle_intersections(a, b, poly[i], r, inters);
            for (int z = 0; z < k; z++) add_candidate(cand, &cnt, inters[z]);
        }

        /* intersections between cell edges and polygon edges are already vertices by clipping,
           but add polygon vertices inside cell */
        for (int j = 0; j < n; j++) {
            if (point_in_convex(cell, m, poly[j])) add_candidate(cand, &cnt, poly[j]);
        }

        /* circle intersections with cell vertices/edges not enough for exact min under radius cap:
           also intersect boundary of cell with circle centered at vertex */
        for (int j = 0; j < m; j++) {
            Point a = cell[j], b = cell[(j + 1) % m];
            Point inters[2];
            int k = seg_circle_intersections(a, b, poly[i], r, inters);
            for (int z = 0; z < k; z++) add_candidate(cand, &cnt, inters[z]);
        }

        for (int j = 0; j < cnt; j++) {
            if (dist2(cand[j], poly[i]) <= r*r + 1e-9) {
                double d2 = dist2(cand[j], poly[i]);
                if (d2 < bestd2) bestd2 = d2;
            }
        }
    }

    if (bestd2 > r*r + 1e-8) return 0.0;
    double ans = 2.0 * sqrt(fmax(0.0, r*r - bestd2));
    return ans;
}

int main(void) {
    int n;
    double r;
    if (scanf("%d %lf", &n, &r) != 2) return 0;

    Point *poly = (Point*)malloc(sizeof(Point) * n);
    for (int i = 0; i < n; i++) scanf("%lf %lf", &poly[i].x, &poly[i].y);

    /* Ensure CCW */
    double area2 = 0;
    for (int i = 0; i < n; i++) area2 += cross(poly[i], poly[(i + 1) % n]);
    if (area2 < 0) {
        for (int i = 0; i < n / 2; i++) {
            Point t = poly[i];
            poly[i] = poly[n - 1 - i];
            poly[n - 1 - i] = t;
        }
    }

    double ans = solve(poly, n, r);
    printf("%.10f\n", ans);

    free(poly);
    return 0;
}

