using namespace std;
using ld = long double;
const ld PI = acos(-1.0L);
const ld EPS = 1e-9;

struct Point {
    ld x, y;
    Point() : x(0), y(0) {}
    Point(ld x_, ld y_) : x(x_), y(y_) {}
};

using Polygon = vector<Point>;

ld cross(const Point &a, const Point &b) {
    return a.x * b.y - a.y * b.x;
}

Point operator-(const Point &a, const Point &b) {
    return Point(a.x - b.x, a.y - b.y);
}

Point operator+(const Point &a, const Point &b) {
    return Point(a.x + b.x, a.y + b.y);
}

Point operator*(const Point &a, ld t) {
    return Point(a.x * t, a.y * t);
}

ld dot(const Point &a, const Point &b) {
    return a.x * b.x + a.y * b.y;
}

ld norm(const Point &p) {
    return sqrtl(p.x * p.x + p.y * p.y);
}

// area of intersection between a circle centered at c with radius r and a convex polygon
ld circlePolygonIntersection(const Polygon &poly, const Point &c, ld r) {
    int n = poly.size();
    ld area = 0;
    for (int i = 0; i < n; i++) {
        Point A = poly[i] - c;
        Point B = poly[(i+1)%n] - c;
        ld a = norm(A);
        ld b = norm(B);
        ld cr = cross(A, B);
        if (a < EPS && b < EPS) {
            area += 0;
        } else if (a < EPS) {
            // A inside, B outside or on edge
            ld theta = acosl(max(-1.0L, min(1.0L, dot(A,B)/(a*b))));
            area += 0.5L * r * r * theta;
        } else if (b < EPS) {
            ld theta = acosl(max(-1.0L, min(1.0L, dot(A,B)/(a*b))));
            area += 0.5L * r * r * theta;
        } else {
            ld theta = acosl(max(-1.0L, min(1.0L, dot(A,B)/(a*b))));
            if (cr > 0) {
                // both outside or crossing
                // check if segment intersects circle
                ld d = fabs(cross(A,B)) / norm(B-A);
                if (d >= r - EPS) {
                    area += 0.5L * r * r * theta;
                } else {
                    // find intersection points
                    Point AB = B - A;
                    ld t = dot(-A, AB) / dot(AB, AB);
                    Point P = A + AB * t;
                    ld h = norm(P);
                    if (h < r - EPS && t > EPS && t < 1-EPS) {
                        // two intersection points
                        ld phi = acosl(h / r);
                        ld alpha = acosl(dot(A, P) / (a * h));
                        ld beta = acosl(dot(B, P) / (b * h));
                        area += 0.5L * r * r * (alpha + beta - phi);
                        area += 0.5L * a * h * sinl(alpha);
                        area += 0.5L * b * h * sinl(beta);
                    } else {
                        area += 0.5L * r * r * theta;
                    }
                }
            } else {
                area += 0.5L * r * r * theta;
            }
        }
    }
    return area;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    int n;
    ld R;
    cin >> n >> R;
    Polygon poly(n);
    for (int i = 0; i < n; i++) {
        cin >> poly[i].x >> poly[i].y;
    }

    // bounding box of polygon
    ld minX = poly[0].x, maxX = poly[0].x;
    ld minY = poly[0].y, maxY = poly[0].y;
    for (auto &p : poly) {
        minX = min(minX, p.x);
        maxX = max(maxX, p.x);
        minY = min(minY, p.y);
        maxY = max(maxY, p.y);
    }

    auto f = [&](ld x, ld y) -> ld {
        return circlePolygonIntersection(poly, Point(x, y), R);
    };

    // ternary search over x and y
    for (int iter3 = 0; iter3 < 60; iter3++) {
        ld m1x = (2*minX + maxX) / 3;
        ld m2x = (minX + 2*maxX) / 3;
        ld bestY1 = minY, bestY2 = minY;
        // find best y for m1x
        ld ly = minY, ry = maxY;
        for (int iterY = 0; iterY < 60; iterY++) {
            ld m1y = (2*ly + ry) / 3;
            ld m2y = (ly + 2*ry) / 3;
            if (f(m1x, m1y) < f(m1x, m2y))
                ly = m1y;
            else
                ry = m2y;
        }
        ld f1 = f(m1x, (ly+ry)/2);
        ly = minY; ry = maxY;
        for (int iterY = 0; iterY < 60; iterY++) {
            ld m1y = (2*ly + ry) / 3;
            ld m2y = (ly + 2*ry) / 3;
            if (f(m2x, m1y) < f(m2x, m2y))
                ly = m1y;
            else
                ry = m2y;
        }
        ld f2 = f(m2x, (ly+ry)/2);
        if (f1 < f2)
            minX = m1x;
        else
            maxX = m2x;
    }

    // final best
    ld bestX = (minX+maxX)/2;
    ld ly = minY, ry = maxY;
    for (int iterY = 0; iterY < 60; iterY++) {
        ld m1y = (2*ly + ry) / 3;
        ld m2y = (ly + 2*ry) / 3;
        if (f(bestX, m1y) < f(bestX, m2y))
            ly = m1y;
        else
            ry = m2y;
    }
    ld bestY = (ly+ry)/2;
    ld ans = f(bestX, bestY);
    cout << fixed << setprecision(9) << ans << "\n";

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

static const double EPS = 1e-10;
static const double PI = acos(-1.0);

struct Pt {
    double x, y;
    Pt() {}
    Pt(double x_, double y_) : x(x_), y(y_) {}
    Pt operator + (const Pt& o) const { return Pt(x + o.x, y + o.y); }
    Pt operator - (const Pt& o) const { return Pt(x - o.x, y - o.y); }
    Pt operator * (double k) const { return Pt(x * k, y * k); }
    Pt operator / (double k) const { return Pt(x / k, y / k); }
};

double dot(Pt a, Pt b) { return a.x * b.x + a.y * b.y; }
double cross(Pt a, Pt b) { return a.x * b.y - a.y * b.x; }
double norm2(Pt a) { return dot(a, a); }
double norm(Pt a) { return sqrt(norm2(a)); }

struct HalfPlane {
    // keeps points p such that cross(dir, p - a) >= 0
    Pt a, dir;
    HalfPlane() {}
    HalfPlane(Pt a_, Pt b_) : a(a_), dir(b_ - a_) {}
};

bool insideHP(const HalfPlane& h, const Pt& p) {
    return cross(h.dir, p - h.a) >= -1e-9;
}

bool lineIntersection(const Pt& p, const Pt& r, const Pt& q, const Pt& s, Pt& out) {
    double rxs = cross(r, s);
    if (fabs(rxs) < EPS) return false;
    double t = cross(q - p, s) / rxs;
    out = p + r * t;
    return true;
}

vector<Pt> clipPolygonWithHalfPlane(const vector<Pt>& poly, const HalfPlane& hp) {
    vector<Pt> res;
    int n = (int)poly.size();
    if (n == 0) return res;
    for (int i = 0; i < n; ++i) {
        Pt A = poly[i];
        Pt B = poly[(i + 1) % n];
        bool inA = insideHP(hp, A);
        bool inB = insideHP(hp, B);

        if (inA && inB) {
            res.push_back(B);
        } else if (inA && !inB) {
            Pt inter;
            lineIntersection(A, B - A, hp.a, hp.dir, inter);
            res.push_back(inter);
        } else if (!inA && inB) {
            Pt inter;
            lineIntersection(A, B - A, hp.a, hp.dir, inter);
            res.push_back(inter);
            res.push_back(B);
        }
    }
    // remove near-duplicate consecutive points
    vector<Pt> clean;
    for (auto &p : res) {
        if (clean.empty() || norm(p - clean.back()) > 1e-9) clean.push_back(p);
    }
    if (clean.size() >= 2 && norm(clean.front() - clean.back()) <= 1e-9) clean.pop_back();
    return clean;
}

double polygonArea(const vector<Pt>& poly) {
    int n = (int)poly.size();
    if (n < 3) return 0.0;
    double s = 0;
    for (int i = 0; i < n; ++i) s += cross(poly[i], poly[(i + 1) % n]);
    return fabs(s) * 0.5;
}

bool pointInConvex(const vector<Pt>& poly, const Pt& p) {
