}

double maxCoveredAreaForRadius(const vector<Pt>& poly, double R) {
    int n = (int)poly.size();
    // Feasible centers are intersection of half-planes:
    // for each edge a->b, center c must satisfy dist(c, line)>=R on inner side
    // => cross(dir, c-a) >= R*|dir|
    // equivalent to cross(dir, c-(a + left_normal_unit*R)) >= 0
    vector<Pt> bigBox = {
        Pt(-1e7, -1e7), Pt(1e7, -1e7), Pt(1e7, 1e7), Pt(-1e7, 1e7)
    };
    vector<Pt> feasible = bigBox;

    for (int i = 0; i < n; ++i) {
        Pt a = poly[i], b = poly[(i + 1) % n];
        Pt d = b - a;
        double len = norm(d);
        Pt leftNormal = Pt(-d.y / len, d.x / len);
        Pt shiftedA = a + leftNormal * R;
        HalfPlane hp(shiftedA, shiftedA + d);
        feasible = clipPolygonWithHalfPlane(feasible, hp);
        if (feasible.empty()) return 0.0;
    }
    return PI * R * R;
}

