import sys
import math

EPS = 1e-10


def dot(a, b):
    return a[0] * b[0] + a[1] * b[1]


def cross(a, b):
    return a[0] * b[1] - a[1] * b[0]


def sub(a, b):
    return (a[0] - b[0], a[1] - b[1])


def add(a, b):
    return (a[0] + b[0], a[1] + b[1])


def mul(a, t):
    return (a[0] * t, a[1] * t)


def norm2(a):
    return a[0] * a[0] + a[1] * a[1]


def dist(a, b):
    return math.hypot(a[0] - b[0], a[1] - b[1])


def polygon_area(poly):
    s = 0.0
    n = len(poly)
    for i in range(n):
        s += cross(poly[i], poly[(i + 1) % n])
    return abs(s) * 0.5


def line_intersection(a, b, c, d):
    # intersection of lines ab and cd
    ab = sub(b, a)
    cd = sub(d, c)
    den = cross(ab, cd)
    if abs(den) < EPS:
        return None
    t = cross(sub(c, a), cd) / den
    return add(a, mul(ab, t))


def clip_polygon_halfplane(poly, a, b):
    # keep left side of directed line a->b
    res = []
    n = len(poly)
    for i in range(n):
        p = poly[i]
        q = poly[(i + 1) % n]
        cp = cross(sub(b, a), sub(p, a))
        cq = cross(sub(b, a), sub(q, a))
        inp = cp >= -EPS
        inq = cq >= -EPS
        if inp and inq:
            res.append(q)
        elif inp and not inq:
            inter = line_intersection(p, q, a, b)
            if inter is not None:
                res.append(inter)
        elif not inp and inq:
            inter = line_intersection(p, q, a, b)
            if inter is not None:
                res.append(inter)
            res.append(q)
    return res


def cut_polygon_by_line(poly, a, b):
    left = clip_polygon_halfplane(poly, a, b)
    right = clip_polygon_halfplane(poly, b, a)
    return left, right


def point_segment_distance(p, a, b):
    ab = sub(b, a)
    ap = sub(p, a)
    bp = sub(p, b)
    dab = norm2(ab)
    if dab < EPS:
        return math.hypot(ap[0], ap[1])
    t = dot(ap, ab) / dab
    if t < 0:
        return math.hypot(ap[0], ap[1])
    if t > 1:
        return math.hypot(bp[0], bp[1])
    proj = add(a, mul(ab, t))
    return dist(p, proj)


def point_in_convex(poly, p):
    n = len(poly)
    for i in range(n):
        if cross(sub(poly[(i + 1) % n], poly[i]), sub(p, poly[i])) < -EPS:
            return False
    return True


def min_enclosing_circle(points):
    # Deterministic O(n^4) worst but fine for small/medium n used here
    pts = points[:]
    n = len(pts)
    if n == 0:
        return ((0.0, 0.0), 0.0)
    if n == 1:
        return (pts[0], 0.0)

    best_c = None
    best_r = float('inf')

    def contains_all(c, r):
        rr = r + 1e-9
        rr2 = rr * rr
        for p in pts:
            if norm2(sub(p, c)) > rr2:
                return False
        return True

    # circles from 2 points
    for i in range(n):
        for j in range(i + 1, n):
            c = ((pts[i][0] + pts[j][0]) * 0.5, (pts[i][1] + pts[j][1]) * 0.5)
            r = dist(c, pts[i])
            if r < best_r and contains_all(c, r):
                best_r = r
                best_c = c

    # circles from 3 points
    for i in range(n):
        for j in range(i + 1, n):
            for k in range(j + 1, n):
                a, b, c = pts[i], pts[j], pts[k]
                d = 2.0 * cross(sub(b, a), sub(c, a))
                if abs(d) < EPS:
                    continue
                aa = norm2(a)
                bb = norm2(b)
                cc = norm2(c)
                ux = (aa * (b[1] - c[1]) + bb * (c[1] - a[1]) + cc * (a[1] - b[1])) / d
                uy = (aa * (c[0] - b[0]) + bb * (a[0] - c[0]) + cc * (b[0] - a[0])) / d
                center = (ux, uy)
                r = dist(center, a)
                if r < best_r and contains_all(center, r):
                    best_r = r
                    best_c = center

    if best_c is None:
        best_c = pts[0]
        best_r = 0.0
    return best_c, best_r


def can_split(poly, R):
    n = len(poly)
    if n <= 2:
        return True

    # If whole polygon already fits in one disk, certainly yes
    _, r0 = min_enclosing_circle(poly)
    if r0 <= R + 1e-9:
        return True

    # Candidate cutting lines:
    # 1) through every pair of vertices
    # 2) perpendicular bisector of every pair of vertices
    candidates = []

    for i in range(n):
        for j in range(i + 1, n):
            a = poly[i]
            b = poly[j]
            if dist(a, b) > EPS:
                candidates.append((a, b))
                mid = ((a[0] + b[0]) * 0.5, (a[1] + b[1]) * 0.5)
                d = sub(b, a)
                perp = (-d[1], d[0])
                candidates.append((mid, add(mid, perp)))

    # also edge directions through each vertex
    for i in range(n):
        a = poly[i]
        b = poly[(i + 1) % n]
        d = sub(b, a)
        for j in range(n):
            p = poly[j]
            candidates.append((p, add(p, d)))

    for a, b in candidates:
        if dist(a, b) < EPS:
            continue
        p1, p2 = cut_polygon_by_line(poly, a, b)
        if len(p1) == 0 or len(p2) == 0:
            continue
        _, r1 = min_enclosing_circle(p1)
        if r1 > R + 1e-9:
            continue
        _, r2 = min_enclosing_circle(p2)
        if r2 > R + 1e-9:
            continue
        return True

    return False


def solve():
    data = sys.stdin.read().strip().split()
    if not data:
        return
    it = iter(data)
    n = int(next(it))
    R = float(next(it))
    poly = []
    for _ in range(n):
        x = float(next(it))
        y = float(next(it))
        poly.append((x, y))

    total = polygon_area(poly)

    # If polygon fits entirely in the disk, answer is full area.
    _, rr = min_enclosing_circle(poly)
    if rr <= R + 1e-9:
        print(f"{total:.10f}")
        return

    # For convex polygon, if it can be split by a line into two parts each coverable by a disk,
    # then one disk can cover at least half the polygon area. Otherwise less than half.
    # Since the polygon is convex and we may choose the better of the two sides,
    # the best guaranteed maximum is:
    # - full area if one disk covers all
    # - otherwise half area iff such a split exists
    # This corresponds to the optimal answer for this problem setting.
    if can_split(poly, R):
        print(f"{(total * 0.5):.10f}")
    else:
        print(f"0.0000000000")


