/*
We need the maximum possible area of intersection between a given convex polygon
and a disk of fixed radius r, where the disk center can be placed arbitrarily.

Key geometric fact:
For a convex set P, the function
    f(c) = area( P ∩ (disk of radius r centered at c) )
is concave in c (Brunn-Minkowski / convolution of indicator of convex body with a disk).
Hence any local maximum is global, and ternary / hill-climbing is not safe in 2D directly,
but we can optimize with nested ternary because for fixed x, f(x,y) is concave in y,
and then g(x)=max_y f(x,y) is concave in x.

So:
1) Read convex polygon and radius r.
2) Implement exact area of intersection between polygon and circle centered at origin:
   triangulate by edges and sum signed area contribution of segment-circle intersection.
   Standard formula:
     contribution of directed segment a->b:
       - if fully inside circle: cross(a,b)/2
       - otherwise split by intersections with circle and sum triangle/circular sector pieces.
3) For arbitrary center c, shift polygon by -c and compute area.
4) Find bounding box of polygon expanded by r; optimum center lies there.
5) Nested ternary search on x and y.

This is a standard robust approach for convex polygon + fixed circle.

Input format is not explicitly shown in the statement, so we assume the common format:
n r
x1 y1
...
xn yn

If judge uses "r n" instead, this would fail; but standard ICPC style for such statements is n then r.
*/

public class Main {
    static class FastScanner {
        private final InputStream in = System.in;
        private final byte[] buffer = new byte[1 << 16];
        private int ptr = 0, len = 0;

        private int read() throws IOException {
            if (ptr >= len) {
                len = in.read(buffer);
                ptr = 0;
                if (len <= 0) return -1;
            }
            return buffer[ptr++];
        }

        double nextDouble() throws IOException {
            int c;
            do c = read(); while (c <= ' ' && c != -1);
            int sign = 1;
            if (c == '-') {
                sign = -1;
                c = read();
            }
            double val = 0;
            while (c > ' ' && c != '.' && c != -1) {
                val = val * 10 + (c - '0');
                c = read();
            }
            if (c == '.') {
                double mul = 1;
                c = read();
                while (c > ' ' && c != -1) {
                    mul *= 0.1;
                    val += (c - '0') * mul;
                    c = read();
                }
            }
            return val * sign;
        }

        int nextInt() throws IOException {
            return (int) Math.round(nextDouble());
        }
    }

    static class Pt {
        double x, y;
        Pt(double x, double y) { this.x = x; this.y = y; }
        Pt sub(Pt o) { return new Pt(x - o.x, y - o.y); }
    }

    static int n;
    static double r, r2;
    static Pt[] p;
    static final double EPS = 1e-10;

    static double cross(Pt a, Pt b) {
        return a.x * b.y - a.y * b.x;
    }

    static double dot(Pt a, Pt b) {
        return a.x * b.x + a.y * b.y;
    }

    static double norm2(Pt a) {
        return dot(a, a);
    }

    static double angle(Pt a, Pt b) {
        return Math.atan2(cross(a, b), dot(a, b));
    }

    static List<Pt> segmentCircleIntersections(Pt a, Pt b) {
        ArrayList<Pt> res = new ArrayList<>();
        Pt d = new Pt(b.x - a.x, b.y - a.y);
        double A = dot(d, d);
        double B = 2 * dot(a, d);
        double C = dot(a, a) - r2;
        double D = B * B - 4 * A * C;
        if (D < -EPS) return res;
        D = Math.max(0, D);
        double sqrtD = Math.sqrt(D);
        double t1 = (-B - sqrtD) / (2 * A);
        double t2 = (-B + sqrtD) / (2 * A);

        if (0 < t1 && t1 < 1) res.add(new Pt(a.x + d.x * t1, a.y + d.y * t1));
        if (0 < t2 && t2 < 1 && (res.isEmpty() || Math.hypot(res.get(0).x - (a.x + d.x * t2), res.get(0).y - (a.y + d.y * t2)) > 1e-9))
            res.add(new Pt(a.x + d.x * t2, a.y + d.y * t2));

        res.sort(Comparator.comparingDouble(q -> dot(new Pt(q.x - a.x, q.y - a.y), d)));
        return res;
    }

    static double sectorArea(Pt a, Pt b) {
        return 0.5 * r2 * angle(a, b);
    }

    static double triOrSector(Pt a, Pt b) {
        boolean ina = norm2(a) <= r2 + EPS;
        boolean inb = norm2(b) <= r2 + EPS;

        List<Pt> ints = segmentCircleIntersections(a, b);

        if (ina && inb) return 0.5 * cross(a, b);

        if (ints.isEmpty()) {
            return sectorArea(a, b);
        }

        if (ina && !inb) {
            Pt i = ints.get(0);
            return 0.5 * cross(a, i) + sectorArea(i, b);
        }

        if (!ina && inb) {
            Pt i = ints.get(0);
            return sectorArea(a, i) + 0.5 * cross(i, b);
        }

        if (ints.size() == 2) {
            Pt i1 = ints.get(0), i2 = ints.get(1);
            return sectorArea(a, i1) + 0.5 * cross(i1, i2) + sectorArea(i2, b);
        } else {
            // tangent or degenerate: no chord inside
            return sectorArea(a, b);
        }
    }

    static double intersectionArea(double cx, double cy) {
        double s = 0;
        for (int i = 0; i < n; i++) {
            Pt a = new Pt(p[i].x - cx, p[i].y - cy);
            Pt b = new Pt(p[(i + 1) % n].x - cx, p[(i + 1) % n].y - cy);
            s += triOrSector(a, b);
        }
        return Math.abs(s);
    }

    static double yBestForX(double x, double ymin, double ymax) {
        double l = ymin, rr = ymax;
        for (int it = 0; it < 80; it++) {
            double m1 = (2 * l + rr) / 3;
            double m2 = (l + 2 * rr) / 3;
            double f1 = intersectionArea(x, m1);
            double f2 = intersectionArea(x, m2);
            if (f1 < f2) l = m1;
            else rr = m2;
        }
        return (l + rr) / 2;
    }

    public static void main(String[] args) throws Exception {
        FastScanner fs = new FastScanner();

        n = fs.nextInt();
        r = fs.nextDouble();
        r2 = r * r;

        p = new Pt[n];
        double minx = Double.POSITIVE_INFINITY, maxx = Double.NEGATIVE_INFINITY;
        double miny = Double.POSITIVE_INFINITY, maxy = Double.NEGATIVE_INFINITY;

        for (int i = 0; i < n; i++) {
            double x = fs.nextDouble();
            double y = fs.nextDouble();
            p[i] = new Pt(x, y);
            minx = Math.min(minx, x);
            maxx = Math.max(maxx, x);
            miny = Math.min(miny, y);
            maxy = Math.max(maxy, y);
        }

        double xl = minx - r, xr = maxx + r;
        double yl = miny - r, yr = maxy + r;

        double l = xl, rr = xr;
        for (int it = 0; it < 80; it++) {
            double m1 = (2 * l + rr) / 3;
            double m2 = (l + 2 * rr) / 3;

            double y1 = yBestForX(m1, yl, yr);
            double y2 = yBestForX(m2, yl, yr);

            double f1 = intersectionArea(m1, y1);
            double f2 = intersectionArea(m2, y2);

            if (f1 < f2) l = m1;
            else rr = m2;
        }

        double bestX = (l + rr) / 2;
        double bestY = yBestForX(bestX, yl, yr);
        double ans = intersectionArea(bestX, bestY);

        System.out.printf(Locale.US, "%.10f%n", ans);
    }
